package net.zartra.gui;
import java.util.*;
final class MenuDefinition {final String id;String title;int rows;String inventoryType="CHEST";String openingCommand="";String openingPermission="";String permissionDenied="&cYou cannot open this menu.";String openingSound="";String closingSound="";long refreshInterval;boolean closeAfterAction;boolean playerInventoryInteraction;boolean itemsTakeable;int maximumViewers;String defaultFillerMaterial="";String paginationPreviousMaterial="ARROW";String paginationNextMaterial="ARROW";final List<Integer> paginationContentSlots=new ArrayList<Integer>();final List<ActionEntry> openActions=new ArrayList<ActionEntry>();final List<ActionEntry> closeActions=new ArrayList<ActionEntry>();final ConditionSet openConditions=new ConditionSet();long createdAt=System.currentTimeMillis();long modifiedAt=System.currentTimeMillis();int formatVersion=3;final Map<Integer,MenuItem> items=new HashMap<Integer,MenuItem>();MenuDefinition(String id,String title,int rows){this.id=id;this.title=title;this.rows=validRows(rows);}static int validRows(int rows){return Math.max(1,Math.min(6,rows));}boolean validPaginationSlots(){Set<Integer>s=new HashSet<Integer>();for(Integer n:paginationContentSlots)if(n==null||n<0||n>=rows*9||!s.add(n))return false;return true;}}